      en: ["Planted by the British in 1866", "Once the main supplier for railway ties", "Includes a zoo and an amusement park", "Irrigated by the Upper Bari Doab Canal", "The name comes from two brothers who were thieves", "An important center for honey-production", "Hosts a wildlife preserve for spotted deer"],
      es: ["Plantado en 1866 por los británicos", "Antiguamente el principal proveedor de traviesas de ferrocarril", "Incluye un zoológico y un parque de atracciones", "Se riega a través del canal Upper Bari Doab", "El nombre proviene de dos hermanos que eran ladrones", "Un centro importante para la producción de miel", "Alberga una reserva de vida silvestre para ciervos axis"],
      pt: ["Plantada em 1866 pelos britânicos", "Outrora o principal fornecedor de travessas de ferrovia", "Inclui um jardim zoológico e um parque de diversões", "É irrigada pelo canal Upper Bari Doab", "O nome provém de dois irmãos que eram ladrões", "Um centro importante para a produção de mel", "Abriga um cercado de vida selvagem para veados axis"],
      fr: ["Plantée en 1866 par les Britanniques", "Autrefois principal fournisseur de traverses de chemin de fer", "Comprend un zoo et un parc d'attractions", "Irriguée par le canal Upper Bari Doab", "Le nom provient de deux frères qui étaient des voleurs", "Un centre important pour la production de miel", "Abrite un enclos animalier pour les cerfs axis"],
