      es: ["Fue reconocido por la UNESCO.", "Protege al raro antílope cervicabra.", "Incluye también humedales y lagos.", "Desempeña un papel importante en la conservación de la naturaleza."],
      pt: ["Foi reconhecido pela UNESCO.", "Protege o raro antílope-negro.", "Inclui também zonas húmidas e lagos.", "Desempenha um papel importante na conservação da natureza."],
