      hu: ["1972-ben nyilvánították nemzeti parkká", "Az UNESCO bioszféra-rezervátumként ismeri el", "A feketeantilop védett területe", "Sivatagi, erdei és vizes ökoszisztémákat foglal magában", "A Patisar-tó fontos hely a vándormadarak számára", "Több mint 160 madárfaj otthona", "Oroszlán-szafarit kínál egy nagy kifutóban"],
