      en: ["Designated a national park in 1972", "Recognized by UNESCO as a Biosphere Reserve", "Sanctuary for the blackbuck antelope", "Includes desert, forest, and wetland ecosystems", "Patisar Lake is a key site for migratory birds", "Home to over 160 species of birds", "Offers lion safaris within a large enclosure"],
      es: ["Designado parque nacional en 1972", "Reconocido por la UNESCO como reserva de la biosfera", "Área protegida para el antílope cervicabra", "Abarca ecosistemas de desierto, bosque y humedales", "El lago Patisar es un sitio clave para aves migratorias", "Hogar de más de 160 especies de aves", "Ofrece safaris de leones en un gran recinto"],
      pt: ["Designado parque nacional em 1972", "Reconhecido pela UNESCO como reserva da biosfera", "Área protegida para o antílope-negro", "Abrange ecossistemas de deserto, floresta e zonas húmidas", "O Lago Patisar é um local importante para aves migratórias", "Lar de mais de 160 espécies de aves", "Oferece safaris de leões num grande recinto"],
      fr: ["Désigné parc national en 1972", "Reconnu par l'UNESCO comme réserve de biosphère", "Zone protégée pour l'antilope cervicapre", "Comprend des écosystèmes de désert, de forêt et de zones humides", "Le lac Patisar est un site important pour les oiseaux migrateurs", "Abrite plus de 160 espèces d'oiseaux", "Propose des safaris aux lions dans un grand enclos"],
