    descriptionAdvanced: {
      de: "Der Margalla-Hills-Nationalpark, am Fuße des Himalaya gelegen, ist ein weitläufiges Schutzgebiet, das direkt an die pakistanische Hauptstadt Islamabad angrenzt. Mit einer Fläche von etwa 17.386 Hektar dient er als grüne Lunge der Stadt und als beliebtes Naherholungsgebiet. Der Park ist bekannt für seine reiche Biodiversität, die Hunderte von Pflanzen- und Tierarten umfasst. Wanderer und Naturliebhaber schätzen das ausgedehnte Netz an Wanderwegen, wie den Trail 3 und Trail 5, die zu Aussichtspunkten wie Daman-e-Koh und Pir Sohawa führen. Von hier aus bieten sich atemberaubende Panoramablicke auf Islamabad. Die Fauna des Parks ist bemerkenswert und umfasst Arten wie den Rhesusaffen, den Muntjak (bellender Hirsch) und gelegentlich sogar den asiatischen Leoparden. Die Bemühungen zur Erhaltung des Parks konzentrieren sich auf den Schutz vor illegaler Abholzung und Urbanisierung, um dieses wertvolle Ökosystem für zukünftige Generationen zu bewahren.",
      hu: "A Margalla Hills Nemzeti Park a Himalája lábánál fekszik, és egy kiterjedt védett terület, amely közvetlenül Pakisztán fővárosával, Iszlámábáddal határos. Körülbelül 17 386 hektáros területével a város zöld tüdejeként és népszerű rekreációs övezetként szolgál. A park gazdag biodiverzitásáról ismert, amely több száz növény- és állatfajt foglal magában. A túrázók és a természetbarátok nagyra értékelik a kiterjedt túraútvonal-hálózatot, mint például a Trail 3 és Trail 5, amelyek olyan kilátópontokhoz vezetnek, mint a Daman-e-Koh és a Pir Sohawa. Innen lélegzetelállító panoráma nyílik Iszlámábádra. A park állatvilága figyelemre méltó, magában foglal olyan fajokat, mint a rhesusmajom, a muntyákszarvas (ugató szarvas) és esetenként még az ázsiai leopárd is. A park megőrzésére irányuló erőfeszítések az illegális erdőirtás és az urbanizáció elleni védelemre összpontosítanak, hogy megőrizzék ezt az értékes ökoszisztémát a jövő generációi számára.",
      ro: "Parcul Național Margalla Hills, situat la poalele Munților Himalaya, este o arie protejată vastă, adiacentă capitalei Pakistanului, Islamabad. Cu o suprafață de aproximativ 17.386 de hectare, acesta servește drept plămânul verde al orașului și o zonă de recreere populară. Parcul este cunoscut pentru biodiversitatea sa bogată, care include sute de specii de plante și animale. Drumeții și iubitorii de natură apreciază rețeaua extinsă de trasee, cum ar fi Trail 3 și Trail 5, care duc la puncte de belvedere precum Daman-e-Koh și Pir Sohawa. De aici, se deschid vederi panoramice uimitoare ale Islamabadului. Fauna parcului este remarcabilă, incluzând specii precum macacul Rhesus, muntiacul (cerbul lătrător) și, ocazional, chiar și leopardul asiatic. Eforturile de conservare a parcului se concentrează pe protejarea împotriva tăierilor ilegale și a urbanizării, pentru a păstra acest ecosistem valoros pentru generațiile viitoare.",
      en: "Margalla Hills National Park, located at the foothills of the Himalayas, is a vast protected area adjacent to Pakistan's capital, Islamabad. Covering approximately 17,386 hectares, it serves as the city's green lung and a popular recreational area. The park is known for its rich biodiversity, which includes hundreds of plant and animal species. Hikers and nature lovers appreciate the extensive network of trails, such as Trail 3 and Trail 5, which lead to viewpoints like Daman-e-Koh and Pir Sohawa. From here, breathtaking panoramic views of Islamabad unfold. The park's fauna is noteworthy, including species like the Rhesus macaque, barking deer (muntjac), and occasionally even the Asian leopard. Conservation efforts focus on protecting the park from illegal logging and urbanization to preserve this valuable ecosystem for future generations.",
      es: "El Parque Nacional de las Colinas de Margalla, situado a los pies del Himalaya, es una extensa área protegida que linda directamente con Islamabad, la capital paquistaní. Con una superficie de unas 17.386 hectáreas, sirve como el pulmón verde de la ciudad y como una popular área de recreo. El parque es conocido por su rica biodiversidad, que incluye cientos de especies de plantas y animales. Los senderistas y amantes de la naturaleza aprecian la extensa red de senderos, como el Trail 3 y el Trail 5, que conducen a miradores como Daman-e-Koh y Pir Sohawa. Desde aquí se ofrecen impresionantes vistas panorámicas de Islamabad. La fauna del parque es notable e incluye especies como el macaco Rhesus, el muntíaco (ciervo ladrador) y, ocasionalmente, incluso el leopardo asiático. Los esfuerzos para preservar el parque se centran en la protección contra la tala ilegal y la urbanización para conservar este valioso ecosistema para las generaciones futuras.",
      pt: "O Parque Nacional das Colinas de Margalla, situado no sopé dos Himalaias, é uma extensa área protegida que faz fronteira direta com Islamabad, a capital paquistanesa. Com uma área de cerca de 17.386 hectares, serve como o pulmão verde da cidade e como uma área de lazer popular. O parque é conhecido pela sua rica biodiversidade, que inclui centenas de espécies de plantas e animais. Os caminhantes e amantes da natureza apreciam a extensa rede de trilhos, como o Trail 3 e o Trail 5, que levam a miradouros como Daman-e-Koh e Pir Sohawa. Daqui, abrem-se vistas panorâmicas deslumbrantes sobre Islamabad. A fauna do parque é notável e inclui espécies como o macaco Rhesus, o muntjac (veado ladrador) e, ocasionalmente, até o leopardo asiático. Os esforços para preservar o parque concentram-se na proteção contra a desflorestação ilegal e a urbanização, de forma a conservar este valioso ecossistema para as gerações futuras.",
      fr: "Le parc national des Margalla Hills, situé au pied de l'Himalaya, est une vaste zone protégée jouxtant directement Islamabad, la capitale pakistanaise. D'une superficie d'environ 17 386 hectares, il sert de poumon vert à la ville et de zone de loisirs populaire. Le parc est réputé pour sa riche biodiversité, comprenant des centaines d'espèces végétales et animales. Les randonneurs et les amoureux de la nature apprécient le vaste réseau de sentiers, tels que le Trail 3 et le Trail 5, menant à des points de vue comme Daman-e-Koh et Pir Sohawa. De là, on profite de panoramas imprenables sur Islamabad. La faune du parc est remarquable et comprend des espèces comme le macaque rhésus, le muntjac (cerf aboyeur) et occasionnellement même le léopard indien. Les efforts de conservation se concentrent sur la protection contre l'exploitation forestière illégale et l'urbanisation afin de préserver ce précieux écosystème pour les générations futures.",
    },
