      hu: ["A Himalája előhegységének része", "A világ harmadik legnagyobb nemzeti parkja", "Több mint 600 növény- és 250 madárfajnak ad otthont", "A Pir Sohawa kilátó népszerű célpont", "A monál, egy fácánfajta, itt is megtalálható", "Leopárdokat időnként kameracsapdákkal észlelnek", "Fontos vízgyűjtő terület Iszlámábád számára"],
      ro: ["Parte a dealurilor de la poalele Himalayei", "Al treilea cel mai mare parc național din lume", "Găzduiește peste 600 de specii de plante și 250 de specii de păsări", "Punctul de belvedere Pir Sohawa este o destinație populară", "Monalul, o specie de fazan, poate fi găsit aici", "Leoparzi sunt ocazional văzuți pe camerele de monitorizare", "Zonă importantă de captare a apei pentru Islamabad"],
      en: ["Part of the Himalayan foothills", "Third largest national park in the world", "Hosts over 600 plant species and 250 bird species", "The Pir Sohawa viewpoint is a popular destination", "Monal pheasants can be found here", "Leopards are occasionally spotted on camera traps", "Important water catchment area for Islamabad"],
      es: ["Parte de las estribaciones del Himalaya", "Tercer parque nacional más grande del mundo", "Ofrece más de 600 especies de plantas y 250 de aves", "El mirador de Pir Sohawa es un destino popular", "Los monales, una especie de faisán, se encuentran aquí", "Se avistan leopardos ocasionalmente en cámaras trampa", "Importante cuenca hidrográfica para Islamabad"],
      pt: ["Parte do sopé dos Himalaias", "Terceiro maior parque nacional do mundo", "Oferece mais de 600 espécies de plantas e 250 de aves", "O miradouro de Pir Sohawa é um destino popular", "Os monais, uma espécie de faisão, encontram-se aqui", "Leopardos são ocasionalmente vistos em armadilhas fotográficas", "Importante bacia hidrográfica para Islamabad"],
      fr: ["Fait partie des contreforts de l'Himalaya", "Troisième plus grand parc national au monde", "Abrite plus de 600 espèces de plantes et 250 d'oiseaux", "Le point de vue de Pir Sohawa est une destination prisée", "Les monals, une espèce de faisan, se trouvent ici", "Des léopards sont parfois vus via des pièges photographiques", "Bassin versant crucial pour l'approvisionnement d'Islamabad"],
