      hu: ["1996-ban alapították a nyugati tragopán védelmére", "Fontos élőhelye a hópárducnak", "Azad Kasmír Neelum-völgyében található", "Mérsékelt övi tűlevelű és lombhullató erdőket foglal magában", "Támogatja a közösségi alapú ökoturizmust", "Magassága 2000 és 4000 méter között változik", "Kulcsszerepet játszik a régió vízkészleteiben"],
      ro: ["Fondat în 1996 pentru a proteja tragopanul occidental", "Habitat important pentru leopardul de zăpadă", "Situat în Valea Neelum din Azad Kashmir", "Include păduri de conifere temperate și de foioase", "Promovează ecoturismul bazat pe comunitate", "Altitudinea variază de la 2000 la 4000 de metri", "Joacă un rol cheie în resursele de apă ale regiunii"],
      en: ["Established in 1996 to protect the Western Tragopan", "Important habitat for the snow leopard", "Located in Neelum Valley, Azad Kashmir", "Comprises temperate coniferous and broadleaf forests", "Promotes community-based ecotourism", "Altitude ranges from 2000 to 4000 meters", "Plays a key role in the region's water resources"],
      es: ["Fundado en 1996 para proteger al tragopán occidental", "Hábitat importante para el leopardo de las nieves", "Ubicado en el valle de Neelum en Azad Cachemira", "Abarca bosques templados de coníferas y caducifolios", "Promueve el ecoturismo basado en la comunidad", "La altitud varía de 2000 a 4000 metros", "Juega un papel clave para los recursos hídricos de la región"],
      pt: ["Fundado em 1996 para proteger o tragopã-ocidental", "Habitat importante para o leopardo-das-neves", "Localizado no Vale do Neelum em Azad Caxemira", "Abrange florestas temperadas de coníferas e folhosas", "Promove o ecoturismo baseado na comunidade", "A altitude varia entre 2000 e 4000 metros", "Desempenha um papel fundamental para os recursos hídricos da região"],
      fr: ["Fondé en 1996 pour protéger le tragopan de Hastings", "Habitat important pour la panthère des neiges", "Situé dans la vallée de Neelum en Azad Cachemire", "Comprend des forêts tempérées de conifères et de feuillus", "Favorise l'écotourisme communautaire", "L'altitude varie de 2000 à 4000 mètres", "Joue un rôle clé pour les ressources en eau de la région"],
