      ro: ["Înființat în 1980 pentru a proteja capra Chiltan", "Numele înseamnă 'de o mie de comori'", "Singurul habitat al caprei sălbatice Chiltan din lume", "Situat lângă Quetta, Balochistan", "Vegetația constă din tufișuri aride, de ienupăr", "Găzduiește și markhorul de Suleiman", "Centru important pentru cercetarea ecosistemelor aride"],
      en: ["Established in 1980 to protect the Chiltan goat", "The name means 'of a thousand treasures'", "Only habitat of the Chiltan wild goat in the world", "Located near Quetta, Balochistan", "Vegetation consists of dry, juniper-like scrubland", "Also home to the Suleiman Markhor", "Important center for arid ecosystem research"],
      es: ["Fundado en 1980 para proteger a la cabra de Chiltan", "El nombre significa 'de mil tesoros'", "Único hábitat de la cabra salvaje de Chiltan en el mundo", "Situado cerca de Quetta, Baluchistán", "La vegetación consiste en matorral seco de tipo enebro", "Alberga también al markhor de Suleimán", "Centro importante para la investigación de ecosistemas de tierras áridas"],
      pt: ["Fundado em 1980 para proteger a cabra de Chiltan", "O nome significa 'de mil tesouros'", "Único habitat da cabra selvagem de Chiltan no mundo", "Localizado perto de Quetta, Baluchistão", "A vegetação consiste em matagal seco de tipo zimbro", "Abriga também o markhor de Suleiman", "Importante centro de investigação de ecossistemas de terras áridas"],
      fr: ["Fondé en 1980 pour protéger la chèvre de Chiltan", "Le nom signifie 'aux mille trésors'", "Seul habitat de la chèvre sauvage de Chiltan au monde", "Situé près de Quetta, au Baloutchistan", "La végétation se compose de broussailles sèches de type genévrier", "Abrite également le markhor de Suleiman", "Centre important pour la recherche sur les écosystèmes arides"],
